 public Phase Phase {get;private set;}=Phase.Player; public int Round {get;private set;}=1; public Cell Console=>Definition.Console??new(6,4); public bool ConsoleUsed {get;private set;} private int robotId; readonly Dictionary<string,Cell> moveOrigins=[];readonly Dictionary<string,IReadOnlyList<Cell>> movePaths=[];public IReadOnlyList<Cell> LastMovePath {get;private set;}=[];public Cell Bridge=>Definition.Bridge??new(9,1);public int BridgeProgress {get;private set;}public string DefeatReason {get;private set;}="";public Cell? Noise {get;private set;}public HashSet<Cell> UsedTraps {get;}=[];
 readonly HashSet<string> scoutRevealed=[];int guardianInterceptRound=-1;bool anesthetistStunUsed;
 public Unit Issac=>Units.FirstOrDefault(u=>u.Role==Role.Officer)??Units.First(u=>u.Team==Team.Player); public int Robots=>Units.Count(u=>u.Alive&&u.Role==Role.Robot); public bool Finished=>Phase is Phase.Victory or Phase.Defeat;
 public bool TurnComplete(Unit u)=>u.Moved&&u.Acted;
 public Unit? NextReadyPlayer()=>Units.FirstOrDefault(u=>u.Alive&&u.Team==Team.Player&&!u.Captured&&!TurnComplete(u));
 public bool PlayerTurnComplete()=>Units.Where(u=>u.Alive&&u.Team==Team.Player&&!u.Captured).All(TurnComplete);
 public BattleState(int mission=1,CampaignState? campaign=null,IEnumerable<string>? roster=null){ Mission=mission; Campaign=campaign??new();var selected=(roster??Campaign.AvailableCrew(mission).Take(4)).ToList();if(!Campaign.ValidateRoster(mission,selected))throw new ArgumentException("Invalid mission roster.",nameof(roster));DeployedIds=selected;progressionSnapshot=Campaign.SnapshotProgressions();foreach(var id in Campaign.AvailableCrew(mission))startingXpTotals[id]=Campaign.Progress(id).Level*100+Campaign.Progress(id).Xp; Definition=MissionDefinition.For(mission); Map=Definition.UnitRows;
 int d=0; for(int y=0;y<12;y++)for(int x=0;x<12;x++){ Unit? u=Map[y][x] switch {
  'X'=>Make("xander","Xander McRaven","X",Role.Scout,Team.Player,18,1,6),'N'=>Make("nance","Nance Parker","N",Role.Shapeshifter,Team.Player,20,1,5),
  'A'=>Make("akiko","Akiko Ikeda","A",Role.Tech,Team.Player,16,1,5),'I'=>Make("issac","Issac Wynter","I",Role.Officer,mission==1?Team.Civilian:Team.Player,18,0,mission==1?0:4),
  'D'=>Make($"droid-{++d}",$"Corrupted droid {d}","D",Role.Droid,Team.Enemy,16,2,3),'H'=>Make("heavy-droid","Corrupted heavy droid","H",Role.HeavyDroid,Team.Enemy,26,4,2),'o'=>null,'e'=>null,'T'=>null,'C'=>mission==3?Make("chrandy","Dr. Chrandy Perra","C",Role.Medic,Team.Player,17,1,5):null,'M'=>Make("ompok-proxy","Ompok proxy","M",Role.OmpokProxy,Team.Enemy,36,4,3),'V'=>Make("vaur","Vaur brute","V",Role.VaurBrute,Team.Enemy,22,3,3),'K'=>Make("khelt","Khelt stalker","K",Role.KheltStalker,Team.Enemy,14,1,5),'Y'=>Make("engineer","Synaptic engineer","Y",Role.SynapticEngineer,Team.Enemy,16,2,4),_=>null}; if(u!=null){u.Position=new(x,y);u.Hidden=mission==3&&u.Role is Role.KheltStalker or Role.SynapticEngineer;Units.Add(u);} }Units.RemoveAll(u=>u.Team==Team.Player&&(u.Hero||u.Role==Role.Officer)&&!selected.Contains(u.Id)); Campaign.Apply(Units);foreach(var medic in Units.Where(u=>u.Role==Role.Medic))medic.MedicalSupplies=medic.ClassProgressions.Contains("chrandy-prepared-1")?5:3;if(mission>=2){var x=Units.FirstOrDefault(u=>u.Role==Role.Scout);var n=Units.FirstOrDefault(u=>u.Role==Role.Shapeshifter);var a=Units.FirstOrDefault(u=>u.Role==Role.Tech);var i=Units.FirstOrDefault(u=>u.Role==Role.Officer);if(x!=null){if(Campaign.XanderUpgrade=="Marksman")x.AttackBonus++;else if(Campaign.XanderUpgrade=="Skirmisher")x.BaseMove++;}if(n!=null){if(Campaign.NanceUpgrade=="Iron Bear")n.BaseArmor++;else if(Campaign.NanceUpgrade=="Enduring Bear")n.BaseHp+=4;}if(a!=null&&Campaign.AkikoUpgrade=="Field Tech")a.BaseHp+=4;if(i!=null&&Campaign.IssacUpgrade=="Combat Training")i.AttackBonus++;if(mission==2)Note("Reach the security-center passage. Any crew member can enter it to complete the mission. Keep Issac and at least one hero alive.");}if(mission==3){Note("Ompok's proxy force reached the Aurora. Stop it before it takes the bridge.");Reveal();}else if(mission==1)Note("Reach Issac and use Rescue from an adjacent tile."); }
 static Unit Make(string id,string name,string token,Role role,Team team,int hp,int armor,int move)=>new(){Id=id,Name=name,Token=token,Role=role,Team=team,BaseHp=hp,Hp=hp,BaseArmor=armor,BaseMove=move};
 public void Note(string s){Log.Add(s);if(Log.Count>30)Log.RemoveAt(0);} public TerrainCell TerrainAt(Cell c)=>Definition.At(c); public bool Floor(Cell c)=>TerrainAt(c).Walkable; public Unit? At(Cell c)=>Units.FirstOrDefault(u=>u.Alive&&u.Position==c);
 void CompleteVictory(string missionKey){if(transactionClosed)return;transactionClosed=true;Campaign.CompletedMissions.Add(missionKey);foreach(var id in DeployedIds){var p=Campaign.Progress(id);MissionXpGains[id]=Math.Max(0,p.Level*100+p.Xp-startingXpTotals.GetValueOrDefault(id,p.Level*100+p.Xp));}var eligible=DeployedIds.Where(id=>!progressionSnapshot.TryGetValue(id,out var saved)||!saved.CompletedMissionIds.Contains(missionKey)).ToList();var gains=eligible.Select(id=>MissionXpGains[id]).ToList();var average=gains.Count==0?0:(int)Math.Round(gains.Average(),MidpointRounding.AwayFromZero);foreach(var id in DeployedIds.Except(eligible))Campaign.RestoreProgression(id,progressionSnapshot);foreach(var id in Campaign.AvailableCrew(Mission).Except(DeployedIds).Where(id=>!Campaign.HasMissionCredit(id,missionKey)))Campaign.AwardXp(id,average);foreach(var id in eligible){var p=Campaign.Progress(id);p.PendingClassProgressions++;p.CompletedMissionIds.Add(missionKey);NewlyRewardedIds.Add(id);}Campaign.GrowBonds(DeployedIds);}
 void RollbackDefeat(){if(transactionClosed)return;transactionClosed=true;Campaign.RestoreProgressions(progressionSnapshot);}
 public bool Command(Unit u)=>Phase==Phase.Player&&u.Alive&&!u.Captured&&u.Team==Team.Player;public bool Enter(Unit u,Cell c)=>Floor(c)&&(Map[c.Y][c.X]!='v'||u.Small);
 public int MovementCost(Cell from,Cell to)=>TerrainAt(from).Elevation==0&&TerrainAt(to).Elevation==1?3:1;
 (Dictionary<Cell,int> costs,Dictionary<Cell,Cell> previous) Search(Unit u,int budget){
  Dictionary<Cell,int> costs=new(){{u.Position,0}};Dictionary<Cell,Cell> previous=[];PriorityQueue<Cell,int> open=new();open.Enqueue(u.Position,0);
  while(open.TryDequeue(out var c,out var queued)){if(queued!=costs[c]||queued>=budget)continue;foreach(var n in c.Neighbors()){
   if(!Enter(u,n)||(At(n)!=null&&n!=u.Position))continue;int next=queued+MovementCost(c,n);if(next>budget||costs.TryGetValue(n,out var old)&&old<=next)continue;
   costs[n]=next;previous[n]=c;open.Enqueue(n,next);
  }}return(costs,previous);
 }
 public Dictionary<Cell,int> Reach(Unit u)=>Search(u,u.Move).costs;
 IReadOnlyList<Cell> PathWithBudget(Unit u,Cell destination,int budget){var search=Search(u,budget);if(!search.costs.ContainsKey(destination))return[];List<Cell> path=[destination];while(path[^1]!=u.Position)path.Add(search.previous[path[^1]]);path.Reverse();return path;}
 public IReadOnlyList<Cell> Path(Unit u,Cell destination)=>PathWithBudget(u,destination,u.Move);
 public bool Move(Unit u,Cell c){if(!Command(u)||u.Moved||c==u.Position||!Reach(u).ContainsKey(c))return false;LastMovePath=Path(u,c);movePaths[u.Id]=LastMovePath;moveOrigins[u.Id]=u.Position;u.Position=c;u.Moved=true;if(u.Id=="xander"&&u.ClassProgressions.Contains("xander-recon-1"))RevealScout(u);if(u.Role==Role.Dog){Reveal();if(Units.Any(x=>!x.Captured&&x.Role==Role.Twin&&x.Position.Distance(u.Position)==1)){Noise=null;Note("A twin calms Tiger down.");}else if(Noise!=null)Noise=u.Position;}Note($"{u.Name} moved.");if(Mission==2&&c==SecurityPassage&&(u.Hero||u.Role==Role.Officer)){u.Acted=true;Award(u,20,"Entered the security center");Phase=Phase.Victory;CompleteVictory("mission-2");Note($"{u.Name} entered the security center. Mission complete!");}return true;}
 void RevealScout(Unit scout){foreach(var enemy in Units.Where(x=>x.Alive&&x.Hidden&&x.Position.Distance(scout.Position)<=3)){enemy.Hidden=false;scoutRevealed.Add(enemy.Id);Note($"Xander spotted {enemy.Name}!");}}
 public bool UndoMove(Unit u){if(!Command(u)||!u.Moved||u.Acted||!moveOrigins.TryGetValue(u.Id,out var origin)||At(origin)!=null)return false;LastMovePath=movePaths.TryGetValue(u.Id,out var original)?original.Reverse().ToList():PathWithBudget(u,origin,144);u.Position=origin;u.Moved=false;moveOrigins.Remove(u.Id);movePaths.Remove(u.Id);Note($"{u.Name} canceled the move.");return true;}
 public IReadOnlyList<Cell> Trace(Cell a,Cell b){int dx=b.X-a.X,dy=b.Y-a.Y,n=Math.Max(Math.Abs(dx),Math.Abs(dy));List<Cell> cells=[];for(int i=1;i<n;i++){var c=new Cell((int)Math.Round(a.X+dx*(double)i/n),(int)Math.Round(a.Y+dy*(double)i/n));if(!cells.Contains(c))cells.Add(c);}return cells;}
 public bool Los(Cell a,Cell b)=>Trace(a,b).All(c=>!TerrainAt(c).BlocksSight);
 public bool HasLowCover(Cell a,Cell b)=>Trace(a,b).Any(c=>TerrainAt(c).Kind==TerrainKind.LowCover);
 public bool Range(Unit a,Cell c,Weapon w)=>a.Position.Distance(c)>0&&a.Position.Distance(c)<=w.Range&&Los(a.Position,c);
 public int BondBonus(Unit u)=>Units.Any(x=>x.Alive&&x.Team==Team.Player&&x!=u&&x.Position.Distance(u.Position)==1&&Campaign.Bond(u.Id,x.Id)>0)?1:0;
 DamageBreakdown PreviewDamageFrom(Unit a,Unit t,Weapon w,Cell from){if(w.StunOnly)return new(0,0,0,0);bool ranged=w.Range>1;int high=ranged&&TerrainAt(from).Elevation>TerrainAt(t.Position).Elevation?2:0;int uphill=ranged&&TerrainAt(from).Elevation<TerrainAt(t.Position).Elevation?1:0;int cover=ranged&&HasLowCover(from,t.Position)&&!(a.Id=="xander"&&a.ClassProgressions.Contains("xander-marksman-2"))?1:0;int guardian=t.Team==Team.Player&&Units.Any(n=>n.Id=="nance"&&n.Alive&&n.Bear&&n.ClassProgressions.Contains("nance-guardian-1")&&n.Position.Distance(t.Position)==1)?1:0;int recon=a.Id=="xander"&&a.ClassProgressions.Contains("xander-recon-2")&&scoutRevealed.Contains(t.Id)?1:0;int damage=Math.Max(1,w.Power+a.AttackBonus+BondBonus(a)-Math.Max(0,t.Armor-recon)-BondBonus(t)-guardian+high-uphill-cover);return new(damage,high,uphill,cover);}
 public DamageBreakdown PreviewDamageBreakdown(Unit a,Unit t,Weapon w)=>PreviewDamageFrom(a,t,w,a.Position);
 public int PreviewDamage(Unit a,Unit t,Weapon w)=>PreviewDamageBreakdown(a,t,w).FinalDamage;
 void Award(Unit actor,int amount,string reason){LastXpAward=0;LastLevelUps=[];LastXpResult=null;var id=actor.ControllerId??(actor.Hero||actor.Role==Role.Officer?actor.Id:null);if(id==null||actor.Team!=Team.Player||amount<=0)return;var before=Campaign.Progress(id).Clone();LastXpAward=amount;LastLevelUps=Campaign.AwardXp(id,amount);var after=Campaign.Progress(id);LastXpResult=new(id,amount,before.Level,before.Xp,after.Level,after.Xp,reason,LastLevelUps);xpAwards.Enqueue(LastXpResult);var owner=Units.FirstOrDefault(x=>x.Id==id);if(owner!=null){owner.Xp=after.Xp;foreach(var level in LastLevelUps){owner.Level=level.Level;switch(level.Path){case TrainingPath.Health:owner.BaseHp+=4;owner.Hp+=4;break;case TrainingPath.Armor:owner.BaseArmor++;break;case TrainingPath.Movement:owner.BaseMove++;break;case TrainingPath.Attack:owner.AttackBonus++;break;}Note($"{owner.Name} reached level {owner.Level}!");}}Note($"{owner?.Name??id} gained {amount} XP: {reason}.");}
 void Hit(Unit a,Unit t,Weapon w){LastXpAward=0;LastXpResult=null;if(t.Role is Role.Twin or Role.Dog){t.Captured=true;t.Acted=t.Moved=true;Note($"{a.Name} captured {t.Name}!");return;}var intended=t;var guardian=t.Team==Team.Player&&t.Id!="nance"&&guardianInterceptRound!=Round?Units.FirstOrDefault(n=>n.Id=="nance"&&n.Alive&&n.Bear&&n.ClassProgressions.Contains("nance-guardian-2")&&n.Position.Distance(t.Position)==1):null;if(guardian!=null){t=guardian;guardianInterceptRound=Round;Note("Nance intercepts the attack!");}var breakdown=PreviewDamageBreakdown(a,intended,w);int damage=breakdown.FinalDamage;t.Hp=Math.Max(0,t.Hp-damage);bool specialStun=w.Stun&&t.Role==Role.OmpokProxy&&a.Id=="chrandy"&&a.ClassProgressions.Contains("chrandy-anesthetist-2")&&!anesthetistStunUsed;if(w.Stun&&t.Alive&&(t.Role!=Role.OmpokProxy||specialStun)){t.Stunned=1;if(specialStun)anesthetistStunUsed=true;}var terrain=breakdown.ModifierSummary.Length>0?$" ({breakdown.ModifierSummary})":"";Note($"{a.Name}: {w.Name} → {t.Name}, {damage} damage{terrain}{(w.Stun&&t.Alive?" + stun":"")}.");if(!t.Alive){Note($"{t.Name} defeated.");if(a.Id=="xander"&&w.Name=="Vibro-axe"&&a.ClassProgressions.Contains("xander-vanguard-2")||a.Id=="nance"&&w.Name=="Bear claws"&&a.ClassProgressions.Contains("nance-fury-2"))a.Moved=false;}if(damage>0)Award(a,t.Alive?25:50,t.Alive?"Damaging attack":"Enemy defeated");}
 public bool Attack(Unit a,Unit t,int i){if(!Command(a)||a.Acted||i<0||i>=a.Weapons.Count||!t.Alive||t.Team==a.Team||t.Team==Team.Civilian||!Range(a,t.Position,a.Weapons[i]))return false;var weapon=a.Weapons[i];if(weapon.StunOnly&&t.Role==Role.OmpokProxy&&!(a.Id=="chrandy"&&a.ClassProgressions.Contains("chrandy-anesthetist-2")&&!anesthetistStunUsed))return false;Hit(a,t,weapon);a.Acted=true;Evaluate();return true;}
 public bool Transform(Unit u){if(!Command(u)||u.Acted||u.Role!=Role.Shapeshifter)return false;if(u.Bear&&u.Hp<=6){Note("Nance needs more than 6 HP to leave Bear form.");return false;}u.Bear=!u.Bear;u.Hp+=u.Bear?6:-6;u.Acted=true;Note($"Nance shifted to {(u.Bear?"Bear":"human")} form.");return true;}
 public IEnumerable<Cell> SummonCells(Unit u)=>u.Position.Neighbors().Where(c=>Floor(c)&&At(c)==null);
 public bool Summon(Unit u,Cell c){int limit=u.ClassProgressions.Contains("akiko-hardened-2")?4:3;if(!Command(u)||u.Acted||u.Role!=Role.Tech||Robots>=limit||!SummonCells(u).Contains(c))return false;var hardened=u.ClassProgressions.Contains("akiko-hardened-1");var r=Make($"robot-{++robotId}",$"Support robot {robotId}","R",Role.Robot,Team.Player,hardened?14:10,hardened?2:1,4);r.ControllerId=u.Id;r.ClassProgressions=[..u.ClassProgressions];r.Position=c;if(Campaign.AkikoUpgrade=="Hardened Robots")r.BaseArmor++;r.Acted=r.Moved=!u.ClassProgressions.Contains("akiko-combat-2");Units.Add(r);u.Acted=true;Award(u,20,"Summoned a support robot");Note("Akiko deployed a robot.");return true;}
 public bool Reprogram(Unit u,Unit d){var threshold=u.ClassProgressions.Contains("issac-override-1")?4:2;if(!Command(u)||u.Acted||u.Role!=Role.Officer||d.Team!=Team.Enemy||d.Role is not (Role.Droid or Role.HeavyDroid)||d.Hp*threshold>d.MaxHp*(threshold-1)||u.Position.Distance(d.Position)!=1)return false;d.Team=Team.Player;d.ControllerId=u.Id;d.ClassProgressions=[..u.ClassProgressions];if(u.ClassProgressions.Contains("issac-command-1"))d.BaseArmor++;if(u.ClassProgressions.Contains("issac-command-2"))d.AttackBonus+=2;d.Acted=d.Moved=!u.ClassProgressions.Contains("issac-override-2");u.Acted=true;Award(u,20,"Reprogrammed an enemy droid");Note($"Issac reprogrammed {d.Name}. It joins your side.");return true;}
 public bool Heal(Unit medic,Unit target){int range=medic.ClassProgressions.Contains("chrandy-prepared-2")?2:1;if(!Command(medic)||medic.Acted||medic.Role!=Role.Medic||medic.MedicalSupplies<=0||target==medic||!target.Alive||target.Team!=Team.Player||target.Role is Role.Robot or Role.Droid or Role.HeavyDroid or Role.OmpokProxy||target.Hp>=target.MaxHp||medic.Position.Distance(target.Position)>range)return false;int amount=Math.Min(medic.ClassProgressions.Contains("chrandy-trauma-1")?10:7,target.MaxHp-target.Hp);target.Hp+=amount;if(medic.ClassProgressions.Contains("chrandy-trauma-2"))target.Stunned=0;medic.MedicalSupplies--;medic.Acted=true;Award(medic,20,"Healed a teammate");Note($"Chrandy treats {target.Name} for {amount} HP ({medic.MedicalSupplies} supplies remain).");return true;}
 public bool Repair(Unit u,Unit target){int range=u.ClassProgressions.Contains("akiko-engineer-1")?2:1;if(!Command(u)||u.Acted||u.Role is not (Role.Tech or Role.Officer)||target.Team!=Team.Player||target.Role is not (Role.Robot or Role.Droid or Role.HeavyDroid)||!target.Alive||target.Hp>=target.MaxHp||u.Position.Distance(target.Position)>range)return false;bool improved=u.ClassProgressions.Contains("akiko-engineer-2")||u.ClassProgressions.Contains("issac-mechanic-1")||Campaign.IssacUpgrade=="Master Mechanic"&&u.Role==Role.Officer;int amount=Math.Min(improved?9:6,target.MaxHp-target.Hp);target.Hp+=amount;if(u.ClassProgressions.Contains("akiko-engineer-2")||u.ClassProgressions.Contains("issac-mechanic-2"))target.Stunned=0;u.Acted=true;Award(u,20,"Repaired an allied machine");Note($"{u.Name} repaired {target.Name} for {amount} HP.");return true;}
 public bool RushTiger(Unit tiger,bool towardTwin){if(!Command(tiger)||tiger.Acted||tiger.Role!=Role.Dog)return false;Unit? target=towardTwin?Units.Where(x=>x.Alive&&!x.Captured&&x.Role==Role.Twin).OrderBy(x=>x.Position.Distance(tiger.Position)).FirstOrDefault():Units.Where(x=>x.Alive&&x.Team==Team.Enemy).OrderBy(x=>x.Position.Distance(tiger.Position)).FirstOrDefault();if(target==null)return false;moveOrigins[tiger.Id]=tiger.Position;tiger.Position=Reach(tiger).Keys.OrderBy(c=>c.Distance(target.Position)).First();tiger.Moved=tiger.Acted=true;Reveal();Note(towardTwin?"Tiger runs back toward the twins.":"Tiger barks and rushes toward the enemy!");Noise=tiger.Position;return true;}
 public void Reveal(){var tiger=Units.FirstOrDefault(x=>x.Alive&&!x.Captured&&x.Role==Role.Dog);if(tiger==null)return;foreach(var enemy in Units.Where(x=>x.Alive&&x.Hidden&&x.Position.Distance(tiger.Position)<=3)){enemy.Hidden=false;Note($"Tiger spotted {enemy.Name}!");}}
 public bool TriggerTrap(Unit u){if(!Command(u)||u.Acted||u.Role!=Role.Twin||!u.Position.Neighbors().Any(c=>Floor(c)&&Map[c.Y][c.X]=='v'))return false;var target=Units.Where(x=>x.Alive&&x.Team==Team.Enemy).OrderBy(x=>x.Position.Distance(u.Position)).FirstOrDefault();if(target==null)return false;target.Hp=Math.Max(0,target.Hp-6);target.Stunned=1;u.Acted=true;Note($"{u.Name} springs a trap: {target.Name} takes 6 damage and is stunned.");Evaluate();return true;}
 public bool RescueCaptive(Unit u){if(!Command(u)||u.Acted||!u.Hero)return false;var captive=Units.FirstOrDefault(x=>x.Alive&&x.Captured&&x.Position.Distance(u.Position)==1);if(captive==null)return false;captive.Captured=false;captive.Acted=captive.Moved=true;u.Acted=true;Award(u,20,"Rescued a captive");Note($"{u.Name} rescued {captive.Name}.");return true;}
 public bool Interact(Unit u){if(!Command(u)||u.Acted)return false;if(Mission==3&&u.Role==Role.Twin)return TriggerTrap(u);if(!u.Hero)return false;if(Mission==1&&u.Position.Distance(Issac.Position)==1&&Issac.Alive){Award(u,20,"Rescued Issac");Phase=Phase.Victory;CompleteVictory("failed-override");Note("Issac rescued. Mission complete!");return true;}if(Definition.Console.HasValue&&!ConsoleUsed&&u.Position.Distance(Console)<=1){var d=Units.Where(x=>x.Alive&&x.Team==Team.Enemy).OrderBy(x=>x.Position.Distance(Console)).FirstOrDefault();if(d==null)return false;d.Stunned=1;ConsoleUsed=true;u.Acted=true;Award(u,20,"Activated a useful console");Note($"Console disabled {d.Name} for one turn.");return true;}return false;}
 public void Wait(Unit u){if(Command(u)){u.Acted=u.Moved=true;Note($"{u.Name} waits.");}}
 public bool WaitForSelectionChange(Unit? current,Unit next){if(current==null||current==next||!Command(current)||TurnComplete(current)||!current.Acted&&!current.Moved)return false;Wait(current);return true;}
 public void StartEnemy(){if(Phase==Phase.Player){Phase=Phase.Enemy;Note("Enemy phase.");}}
 void AdvanceTowardObjective(Unit unit,Cell objective){
  var route=objective.Neighbors().Where(c=>TerrainAt(c).Walkable&&(At(c)==null||c==unit.Position)).Select(c=>PathWithBudget(unit,c,144)).Where(p=>p.Count>0).OrderBy(p=>p.Zip(p.Skip(1),(a,b)=>MovementCost(a,b)).Sum()).FirstOrDefault();
  if(route==null){LastMovePath=[unit.Position];return;}int spent=0,index=0;for(int i=1;i<route.Count;i++){int step=MovementCost(route[i-1],route[i]);if(spent+step>unit.Move)break;spent+=step;index=i;}LastMovePath=route.Take(index+1).ToList();unit.Position=route[index];
 }
 public void Enemy(Unit e){if(Phase!=Phase.Enemy||!e.Alive)return;LastMovePath=[e.Position];e.Hidden=false;if(e.Stunned>0){e.Stunned--;Note($"{e.Name} is stunned.");return;}if(e.Role==Role.OmpokProxy){if(e.Position.Distance(Bridge)<=1){BridgeProgress++;Note($"Ompok links to the bridge ({BridgeProgress}/2)!");if(BridgeProgress>=2){DefeatReason="Ompok completed the bridge takeover.";Phase=Phase.Defeat;RollbackDefeat();Note(DefeatReason);}return;}var start=e.Position;AdvanceTowardObjective(e,Bridge);Note(e.Position==start?"Ompok waits.":"Ompok advances toward the bridge.");return;}var targets=Units.Where(u=>u.Alive&&!u.Captured&&u.Team==Team.Player).OrderByDescending(u=>Noise!=null&&u.Role==Role.Dog).ToList();var captive=Units.FirstOrDefault(x=>x.Role==Role.Officer);if(Round>=6&&captive!=null&&!targets.Contains(captive))targets.Add(captive);if(targets.Count==0){Note($"{e.Name} waits.");Evaluate();return;}var option=(from c in Reach(e) from t in targets from w in e.Weapons where c.Key.Distance(t.Position)>0&&c.Key.Distance(t.Position)<=w.Range&&Los(c.Key,t.Position) orderby (Noise!=null&&t.Role==Role.Dog?0:1),t.Team==Team.Civilian,PreviewDamageFrom(e,t,w,c.Key).FinalDamage descending,c.Value select(c:c.Key,t,w)).FirstOrDefault();if(option.t!=null){LastMovePath=Path(e,option.c);e.Position=option.c;Hit(e,option.t,option.w);}else{var target=targets.OrderBy(t=>t.Position.Distance(e.Position)).First();var start=e.Position;var advanceDestination=Reach(e).Keys.OrderBy(c=>c.Distance(target.Position)).First();LastMovePath=Path(e,advanceDestination);e.Position=advanceDestination;Note(e.Position==start?$"{e.Name} waits.":$"{e.Name} advances.");}Evaluate();}
 public void StartPlayer(){if(Phase!=Phase.Enemy)return;Round++;Phase=Phase.Player;moveOrigins.Clear();foreach(var u in Units.Where(u=>u.Alive&&u.Team==Team.Player)){if(u.Id=="nance"&&u.Bear&&u.ClassProgressions.Contains("nance-iron-2"))u.Hp=Math.Min(u.MaxHp,u.Hp+3);u.SkippedByStun=u.Stunned>0;u.Moved=u.Acted=u.SkippedByStun;if(u.Stunned>0){u.Stunned--;Note($"{u.Name} is stunned this phase.");}}Noise=null;Note($"Player phase · round {Round}.");}
 public void Evaluate(){if(Finished)return;if(Mission==3&&!Units.Any(x=>x.Alive&&x.Team==Team.Enemy)){Phase=Phase.Victory;CompleteVictory("mission-3");Note("Ompok’s proxy force is defeated!");return;}var issac=Units.FirstOrDefault(x=>x.Role==Role.Officer);bool defeated=Mission switch {1=>issac==null||!issac.Alive||!Units.Any(u=>u.Alive&&u.Hero),2=>issac==null||!issac.Alive||!Units.Any(u=>u.Alive&&u.Hero),3=>!Units.Any(u=>u.Alive&&(u.Hero||u.Role==Role.Officer)),_=>false};if(defeated){DefeatReason=Mission==3?"Every combat-capable crew member was defeated.":issac==null||!issac.Alive?"Issac was killed.":"All three heroes were defeated.";Phase=Phase.Defeat;RollbackDefeat();Note(DefeatReason);}}
}
